"""Shared helpers for the door checks: render OpenSCAD bodies, slice them, measure gaps and overhangs.
Needs: openscad, python3 with trimesh + rtree + shapely + numpy."""
import math, os, re, subprocess, sys, tempfile
import numpy as np, trimesh
from shapely.geometry import Polygon, Point, LineString, box
from shapely.ops import unary_union

HERE = os.path.dirname(os.path.abspath(__file__))
TMP = tempfile.mkdtemp(prefix='doorcheck_')


def defs_from_argv():
    """-D style overrides from the command line: name=value (e.g. cj=0.35)."""
    return [a for a in sys.argv[1:] if re.match(r'^[A-Za-z_]\w*=', a)]


def scad_echo(scad, defs=()):
    """Values printed by the SCAD file's part="echo" (one ECHO line 'GEO k=v;k=v...')."""
    fn = os.path.join(TMP, os.path.basename(scad) + '.echo')
    subprocess.run(['openscad', '-D', 'part="echo"', *sum((['-D', d] for d in defs), []), '-o', fn, scad], check=True,
                   stderr=subprocess.DEVNULL)   # -q would also drop the ECHO lines
    txt = open(fn).read()
    body = txt.split('GEO ', 1)[1].rsplit('"', 1)[0]
    out = {}
    for kv in body.split(';'):
        k, v = kv.split('=', 1)
        out[k] = eval(v.replace('true', 'True').replace('false', 'False').replace('undef', 'None'))
    return out


def render(scad, part, defs=()):
    fn = os.path.join(TMP, f'{os.path.basename(scad)}.{part}.stl')
    r = subprocess.run(['openscad', '--export-format', 'binstl', '-D', f'part="{part}"',
                        *sum((['-D', d] for d in defs), []), '-o', fn, scad], check=True, capture_output=True, text=True)
    bad = [l for l in r.stderr.splitlines() if l.startswith('ERROR') or 'undefined' in l.lower()]
    if bad:                                     # OpenSCAD keeps going and silently drops the broken geometry
        sys.exit(f'{os.path.basename(scad)} part {part}: ' + '; '.join(bad[:3]))
    return trimesh.load(fn)


def slices(mesh, zs):
    out = {}
    secs = mesh.section_multiplane(plane_origin=[0, 0, 0], plane_normal=[0, 0, 1], heights=list(zs))
    for z, s in zip(zs, secs):
        if s is None:
            out[z] = Polygon(); continue
        polys = [p for p in s.polygons_full if p.area > 1e-4]
        out[z] = unary_union(polys).buffer(0) if polys else Polygon()
    return out


def layer_zs(z_top, extra=()):
    layers = sorted(set(np.round(np.arange(0.1, z_top, 0.2), 3).tolist()))
    return layers, sorted(set(layers + list(extra)))


def overhangs(sl, layers, min_area=1.0):
    """Area of each layer not resting on the layer below (45 deg = 0.2 mm per 0.2 mm layer)."""
    items = []
    for z0, z1 in zip(layers, layers[1:]):
        lo, up = sl[z0], sl[z1]
        un = up.difference(lo.buffer(0.2 + 0.05))
        if un.area > min_area:
            w = max((g.area / max(g.length, 1e-6)) * 2 for g in (un.geoms if hasattr(un, 'geoms') else [un]))
            items.append((z1, un.area, w))
    return items


def screw_walls(sl, screws, r_cb, zmax, wall=1.5):
    """Missing plastic area in a ring of `wall` mm around each counterbore (worst layer below zmax)."""
    res = []
    for sx, sy in screws:
        ring = Point(sx, sy).buffer(r_cb + wall).difference(Point(sx, sy).buffer(r_cb + 0.15))
        worst = min(ring.difference(sl[z]).area for z in sl if z < zmax)
        res.append(((sx, sy), worst))
    return res


def footprint(polys):
    g = unary_union(polys)
    x0, y0, x1, y1 = g.bounds
    return x1 - x0, y1 - y0


def strip(a, b, z, zc, r):
    """Cross-section at height z of a cylinder (axis a-b in the plane z = zc, radius r): a capsule or None."""
    dz = abs(z - zc)
    if dz >= r: return None
    return LineString([tuple(a), tuple(b)]).buffer(math.sqrt(r * r - dz * dz), 16)


def fmt_gap(v):
    return '   -  ' if v > 1e8 else f'{v:6.2f}'

// Robo-Garage flap out - printed parts (OpenSCAD, FOSS)
// David Gölzhäuser (idoodler) - https://github.com/idoodler/robo-garage
//
// A flush 18 mm flap (596 x 207 mm) hangs on a piano hinge at its top front edge and swings up and out to 90 deg.
// A lever on its back reaches 90 mm above the hinge; the actuator stands right behind the drawer front on the
// left cheek and pushes the lever tip down and back. Replaces the bent steel L-bracket.
//
// Frame (mm): X = depth behind the cheek front edge, Y = height above the floor (tray top = 15),
// W = distance from the left cheek's inner face towards the robot bay. Hinge axis: X -19, Y 224.
//
// part = "lever"   1x: screwed to the flap's back (3 screws 3.5 x 25), M6 bolt for the rod eye
//        "mount"   1x: actuator top mount on the left cheek (3 screws 4 x 25, +-8 mm slots), spacer printed with it
//        "set"     both on one bed
//        "scene"   side view of the left cheek from the bay; `pose` 0 = closed .. 1 = open (90 deg)

version = "1.0";

/* [Output] */
part = "scene";         // [lever, mount, set, scene]
pose = 0;               // [0:0.05:1]

/* [Hardware] */
eye_bolt = 6;           // M6 bolts for both actuator eyes
act_len = 225;          // actuator pin to pin, retracted
wall_screw = 4;         // mount: 4 mm countersunk wood screws
flap_screw = 3.5;       // lever: 3.5 x 25 countersunk into the flap's back

/* [Hidden] */
$fn = 48;
H = [-19, 224];                         // hinge axis
PIN = [37, 315.5];                      // lever pin, closed: 56 mm behind and 91.5 mm above the hinge (chord 152 mm)
lv_w = [8, 20];                         // lever plane (W), rod eye on its bay side with a washer
eye_w = lv_w[1] + 1 + 4;                // actuator centre plane (8 mm eyes)
lv_t = 14;                              // lever depth on the flap's back (X 0..14)
lv_y0 = 144;                            // lower end on the flap
SCREWS = [154, 180, 206];               // flap screws (Y), all below the hinge line
stroke = 150;
// actuator top pivot: act_len from the closed pin and act_len + stroke from the open pin, on the cheek side
function rotH(p, a) = H + [[cos(a), sin(a)], [-sin(a), cos(a)]] * (p - H);   // clockwise by a (flap opening)
PIN1 = rotH(PIN, 90);
CH_ = norm(PIN - PIN1);
TH_ = acos((act_len * act_len + CH_ * CH_ - (act_len + stroke) * (act_len + stroke)) / (2 * act_len * CH_));
A_ = atan2(PIN[1] - PIN1[1], PIN[0] - PIN1[0]);
F = PIN + act_len * [cos(A_ - (180 - TH_)), sin(A_ - (180 - TH_))];

module disk(c, r) translate(c) circle(r = r);
function nut_af(d) = d >= 6 ? 10 : d >= 5 ? 8 : 7;

// ---------------------------------------------------------------- lever (world frame, closed)
module lever_profile() union() {
  translate([0, lv_y0]) square([lv_t, PIN[1] + 10 - lv_y0]);                     // along the flap's back
  hull() { translate([0, PIN[1] - 10]) square([lv_t, 20]); disk(PIN, 10); }      // arm to the pin
  translate([lv_t, PIN[1] - 10]) polygon([[0, 0], [0, -22], [22, 0]]);            // gusset under the arm
}
module lever_world() difference() {
  translate([0, 0, lv_w[0]]) linear_extrude(lv_w[1] - lv_w[0]) lever_profile();
  translate([PIN[0], PIN[1], lv_w[0] - 1]) cylinder(d = eye_bolt + 0.4, h = 20, $fn = 32);
  translate([PIN[0], PIN[1], lv_w[0] - 1]) cylinder(d = (nut_af(eye_bolt) + 0.4) / cos(30), h = 6, $fn = 6);   // nut, cheek side
  for (y = SCREWS) translate([lv_t + 0.01, y, (lv_w[0] + lv_w[1]) / 2]) rotate([0, -90, 0]) {   // countersunk from the back
    cylinder(d = flap_screw + 0.4, h = lv_t + 1, $fn = 24);
    cylinder(d1 = 2 * flap_screw + 0.6, d2 = flap_screw + 0.4, h = flap_screw / 2 + 0.2, $fn = 32);
  }
}
module lever() translate([0, 0, -lv_w[0]]) lever_world();          // printed on its side: all features in the X-Y profile

// ---------------------------------------------------------------- top mount (left cheek, printed cheek face down)
mt = 14;  mslot = 8;
MS = [F + [-14, 18], F + [24, 18], F + [-14, -8]];
module mount_block() difference() {
  union() {
    linear_extrude(mt) hull() { disk(F, 11); disk(F + [-14, -18], 9.5); disk(F + [-14, 27], 9.5); disk(F + [24, 27], 9.5); }
    translate([F[0], F[1], mt - 0.01]) cylinder(d = 22, h = eye_w - 4 - 1 - mt + 0.01, $fn = 48);   // boss: top = eye face (with washer)
  }
  translate([F[0], F[1], -1]) cylinder(d = eye_bolt + 0.4, h = eye_w + 2, $fn = 32);
  translate([F[0], F[1], -1]) cylinder(d = (nut_af(eye_bolt) + 0.4) / cos(30), h = 7, $fn = 6);
  for (s = MS) {
    d = wall_screw + 0.5;  dc = 2 * wall_screw + 0.6;
    hull() for (dy = [-mslot, mslot]) translate([s[0], s[1] + dy, -1]) cylinder(d = d, h = mt + 2, $fn = 24);
    hull() for (dy = [-mslot, mslot]) translate([s[0], s[1] + dy, mt - (dc - d) / 2]) cylinder(d1 = d, d2 = dc, h = (dc - d) / 2 + 0.01, $fn = 32);
  }
  translate([F[0] + 5, F[1] + 18, mt - 0.6]) linear_extrude(1) text("UP", size = 6, halign = "center", valign = "center");
}
module mount() mount_block();

module set() {
  translate([10, -lv_y0 + 10, 0]) lever();
  translate([110 - F[0], 60 - F[1], 0]) mount();
}

// ---------------------------------------------------------------- scene
module scene(f) {
  a = 90 * f;
  module rot() translate([H[0], H[1], 0]) rotate(-a) translate([-H[0], -H[1], 0]) children();
  color("Tan", 0.6) rot() translate([-19, 17, -60]) cube([19, H[1] - 17, 60 + 18]);        // flap
  color("SteelBlue") rot() lever_world();
  p = rotH(PIN, a);
  color("SlateGray") mount_placed();
  color("DimGray") hull() { translate([F[0], F[1], eye_w - 6]) cylinder(d = 26, h = 2); translate([F[0], F[1], eye_w - 6] + concat((p - F) / norm(p - F) * 190, [0])) cylinder(d = 26, h = 2); }
  color("Silver") hull() { translate([F[0], F[1], eye_w - 6] + concat((p - F) / norm(p - F) * 150, [0])) cylinder(d = 14, h = 2); translate([p[0], p[1], eye_w - 6]) cylinder(d = 14, h = 2); }
  CH = [[0, 15], [250, 15], [250, 47], [100, 247], [100, 620], [0, 620]];
  color("SaddleBrown") translate([0, 0, -80]) linear_extrude(1) difference() { polygon(CH); offset(delta = -2) polygon(CH); }
  color("Tan") translate([-19, 225, -80]) cube([16, 395, 1]);
  color("Sienna") translate([-19, 3, -80]) cube([19 + 250, 12, 1]);
}
module mount_placed() mount_block();     // printed cheek face down = W 0 on the cheek

if (part == "echo") echo(str("GEO F=", F, ";PIN=", PIN, ";PIN1=", PIN1, ";H=", H, ";act_len=", act_len, ";stroke=", stroke, ";eye_w=", eye_w, ";lv_w=", lv_w, ";lv_t=", lv_t, ";lv_y0=", lv_y0, ";version='", version, "'"));
else if (part == "lever") lever();
else if (part == "w_lever") lever_world();
else if (part == "w_mount") mount_placed();
else if (part == "mount") mount();
else if (part == "set") set();
else if (part == "scene") scene(pose);

#!/usr/bin/env python3
"""Check the simple door types: lift door (lift-door.scad) and flap out (flap.scad).
Lift door: printed parts do not touch each other or the panel over the whole lift, saddle clear of the drawer front.
Flap: actuator stroke, lever arm and holding force over the swing, lever + flap clear of the drawer front.
Usage: python3 check_simple.py"""
import math, os, sys
import numpy as np
from shapely.geometry import box, Polygon, LineString, Point
from shapely import affinity
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from checklib import HERE, scad_echo, render, slices

ok, report = True, []
def fail(m):
    global ok; ok = False; report.append(m)

# ---------------- lift door
SC = os.path.join(HERE, 'lift-door.scad'); G = scad_echo(SC)
ws = np.round(np.arange(0.25, 60, 0.5), 2)
body = {k: slices(render(SC, 'w_' + k), ws) for k in ('channel', 'saddle', 'foot', 'clamp')}
lift = G['stroke'] - (G['seat_y'] - G['tip_y'])                  # panel travel: stroke minus the 3 mm air at the cup
panel = box(G['door_x'][0], G['door_y'][0], G['door_x'][1], G['door_y'][1])
vedd = box(-19, 225, -3, 700)
worst = {'saddle-channel': 1e9, 'saddle-clamp': 1e9, 'saddle-foot': 1e9, 'clamp-channel': 1e9, 'foot-channel': 1e9, 'saddle-drawer front': 1e9, 'panel-clamp': 1e9, 'panel-foot': 1e9}
for L in np.linspace(0, lift, 31):
    for w in ws:
        sd = affinity.translate(body['saddle'][w], 0, L)
        pn = affinity.translate(panel, 0, L) if w >= 3 else None              # panel edge 3 mm from the cheek
        for k in ('channel', 'clamp', 'foot'):
            g = body[k][w]
            if not sd.is_empty and not g.is_empty: worst['saddle-' + k] = min(worst['saddle-' + k], sd.distance(g))
            if pn is not None and k != 'channel' and not g.is_empty: worst['panel-' + k] = min(worst['panel-' + k], pn.distance(g))
        if not sd.is_empty: worst['saddle-drawer front'] = min(worst['saddle-drawer front'], sd.distance(vedd))
        for k in ('clamp', 'foot'):
            a, b = body[k][w], body['channel'][w]
            if not a.is_empty and not b.is_empty: worst[k + '-channel'] = min(worst[k + '-channel'], a.distance(b))
print(f'--- lift door: panel rises {lift:.0f} mm (opening {G["door_y"][0] + lift - 15:.0f} mm above the tray)')
print('  gaps (mm): ' + ', '.join(f'{k} {v:.1f}' if v < 1e8 else f'{k} apart' for k, v in worst.items()))
for k, v in worst.items():
    if v < (0.3 if k in ('clamp-channel', 'foot-channel') else 1.0): fail(f'lift door: {k} {v:.1f} mm')
if G['door_y'][0] + lift - 15 < 125: fail('lift door: opening too low for the robot')

# ---------------- flap
SC = os.path.join(HERE, 'flap.scad'); G = scad_echo(SC)
H, PIN, F = (np.array(G[k], float) for k in ('H', 'PIN', 'F'))
def rot(p, a):                                       # clockwise about the hinge (flap opening)
    c, s = math.cos(math.radians(a)), math.sin(math.radians(a)); q = np.array(p) - H
    return H + np.array([c * q[0] + s * q[1], -s * q[0] + c * q[1]])
l0, l1 = np.linalg.norm(F - rot(PIN, 0)), np.linalg.norm(F - rot(PIN, 90))
W, cg = 17.2, np.array([-9.5, 224 - 103.5])          # flap 596 x 207 x 19 MDF
arms, forces = [], []
for a in np.linspace(0, 90, 91):
    p = rot(PIN, a); u = (F - p) / np.linalg.norm(F - p); r = p - H
    arm = abs(r[0] * u[1] - r[1] * u[0]); arms.append(arm)
    g = rot(cg, a) - H; forces.append(W * abs(g[0]) / arm)
lv = slices(render(SC, 'w_lever'), [G['lv_w'][0] + 6])[G['lv_w'][0] + 6]
flap = box(-19, 17, 0, 224)
dl = min(affinity.rotate(lv, -a, origin=tuple(H)).distance(vedd) for a in np.linspace(0, 90, 46))
df = min(affinity.rotate(flap, -a, origin=tuple(H)).distance(vedd) for a in np.linspace(0.5, 90, 46))
mt = render(SC, 'w_mount'); lo, hi = mt.bounds
print(f'--- flap: actuator {l0:.1f} -> {l1:.1f} mm (stroke {l1 - l0:.1f}), lever arm {min(arms):.0f}..{max(arms):.0f} mm, '
      f'holding force max {max(forces):.0f} N; lever {dl:.1f} mm and flap {df:.1f} mm from the drawer front; mount X {lo[0]:.0f}..{hi[0]:.0f} Y {lo[1]:.0f}..{hi[1]:.0f}')
if abs(l1 - l0 - G['stroke']) > 1: fail('flap: stroke mismatch')
if min(arms) < 50: fail('flap: lever arm below 50 mm')
if max(forces) > 35: fail('flap: holding force above 35 N')
if dl < 2 or df < 0.5: fail('flap: touches the drawer front')
if lo[0] < 2 or hi[1] > 578: fail('flap: mount off the cheek or into the top rail')
print('RESULT:', 'OK' if ok else 'PROBLEMS\n  ' + '\n  '.join(report))
sys.exit(0 if ok else 1)
